def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = g[0][0]
    div = next((i for i, row in enumerate(g) if all(v == 2 for v in row)), None)
    if div is None:
        return g
    pts = [(r, c) for r in range(h) for c in range(w)
           if r != div and g[r][c] not in (bg, 2)]
    if not pts:
        return g
    top, bottom = min(r for r, _ in pts), max(r for r, _ in pts)
    left, right = min(c for _, c in pts), max(c for _, c in pts)
    if top > div:
        obj = [row[left:right + 1] for row in g[top:bottom + 1]]
        for r, c in pts:
            g[r][c] = bg
        start = div + 1
        for dr, row in enumerate(obj):
            if start + dr < h:
                for dc, value in enumerate(row):
                    if value != bg:
                        g[start + dr][left + dc] = value
        stripe = start + len(obj)
    else:
        # The 8 stripe marks the row immediately after the object's uppermost row.
        stripe = top + 1
    if 0 <= stripe < h:
        g[stripe] = [8] * w
    return g
